INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "阿鲁台", "aliases": ["和宁王"], "era": "明", "birth_year": null, "death_year": null, "description": "阿鲁台受封和宁王。", "biography": null, "status": "draft", "id": "fd6d854f-724b-5621-91d3-593e412f448b"}, {"name": "吕震（明代官员）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，永乐3年（年号对照1405年）九月，吕震出任刑部尚书。", "biography": null, "status": "draft", "id": "d58bc9ab-d97e-592e-909f-284f788a262a"}, {"name": "朱棣", "aliases": ["明成祖"], "era": "明", "birth_year": null, "death_year": null, "description": "明成祖，建文4年（1402年），朱棣即皇帝位。", "biography": null, "status": "draft", "id": "dd806a37-77e8-5244-96e9-4d71db81b600"}, {"name": "胡广（明代内阁大学士）", "aliases": ["胡廣"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（1402年）九月，胡广以翰林侍讲身份入直文渊阁。", "biography": null, "status": "draft", "id": "c9d78e04-f4b5-58bb-9869-c02bda75f0d3"}, {"name": "纪纲", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "纪纲主管锦衣卫事务，获罪被处死。", "biography": null, "status": "draft", "id": "c613ae3d-80de-5c59-a19f-07ad2cc84b42"}, {"name": "张辅", "aliases": ["张文弼"], "era": "明", "birth_year": null, "death_year": null, "description": "张辅率军在爱子江交战。", "biography": null, "status": "draft", "id": "ef0d049d-1c37-5697-84d4-4274dfac2d2d"}, {"name": "朱高煦", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "汉王。宣德元年（年号对照1426年），本表记录了朱高煦的活动。", "biography": null, "status": "draft", "id": "b6d6c246-3315-52c1-b7c1-e0ebc937a6ce"}, {"name": "郑和", "aliases": ["鄭和"], "era": "明", "birth_year": null, "death_year": null, "description": "明代中官。本纪载其于永乐三年率舟师出使西洋各国。", "biography": null, "status": "draft", "id": "9a24d146-cea1-5746-85e4-479becda6195"}, {"name": "陈瑄", "aliases": ["陈彦纯", "平江伯"], "era": "明", "birth_year": null, "death_year": null, "description": "陈瑄以平江伯身份督办漕运并转运木材。", "biography": null, "status": "draft", "id": "104b6c7a-fa0b-5961-86b0-c745c1c2ad68"}, {"name": "李彬", "aliases": ["丰城侯"], "era": "明", "birth_year": null, "death_year": null, "description": "李彬以丰城侯身份率领右哨。", "biography": null, "status": "draft", "id": "04c63363-9652-5acf-9921-b7fbfbf6b56d"}, {"name": "陈珪（明初泰宁侯）", "aliases": ["泰宁侯"], "era": "明", "birth_year": null, "death_year": null, "description": "陈珪以泰宁侯身份主持营建北京。", "biography": null, "status": "draft", "id": "4424e48a-b752-55b6-9c2d-cfa9565c58eb"}, {"name": "柳升", "aliases": ["安远侯"], "era": "明", "birth_year": null, "death_year": null, "description": "柳升以安远侯身份率领大营。", "biography": null, "status": "draft", "id": "14f79103-5514-5b8a-b46f-74887204ab53"}, {"name": "朱高炽", "aliases": ["明仁宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明仁宗，永樂22年（1424年）八月，朱高炽即皇帝位。", "biography": null, "status": "draft", "id": "2dded14d-7183-56b5-9029-ca93826c1e80"}, {"name": "赵羾", "aliases": ["趙羾"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，永乐5年（年号对照1407年）六月，赵羾出任礼部尚书。", "biography": null, "status": "draft", "id": "9b6df04e-fb7c-53e4-a883-249e1c0b7e31"}]'::jsonb)
