INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明廷免除灾区积欠并发粮赈饥", "description": "永乐十四年正月己酉，北京、河南、山东发生饥荒。明廷免去当地永乐十二年尚未缴清的田租，并拨出一百三十七万余石粮食救济。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年正月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ecaceeeb-df55-5a77-8e0f-bde24427bd04"}, {"title": "都督金玉出兵广灵山区", "description": "永乐十四年正月辛酉，都督金玉出兵攻打本纪所称的山西广灵山寇，并平息当地战事。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年正月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "879d19df-13ab-5778-83ca-6bdd966df1ca"}, {"title": "都督梁福奉命镇守湖广、贵州", "description": "永乐十四年三月癸巳，朝廷派都督梁福镇守湖广和贵州。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年三月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a2170dc3-f72e-5ff2-a1e6-1fb1299ff44e"}, {"title": "阿鲁台击败瓦剌后向明廷报捷", "description": "永乐十四年三月壬寅，本纪载阿鲁台击败瓦剌，随后向明廷报告战果。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年三月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b78e4e37-fee7-5411-959f-58cbfce56fa2"}, {"title": "吕震请举行封禅，明成祖拒绝", "description": "永乐十四年四月壬申，礼部尚书吕震请求举行封禅礼。明成祖朱棣说，各地仍有水灾、旱灾和疫病，不能自称太平，六经也没有封禅的记载，因此没有采纳。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年四月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dba0d434-240e-51fd-bc5f-289e09d9ed24"}, {"title": "胡广升任文渊阁大学士，仍兼原有春坊、翰林职务", "description": "永樂14年（1416年）四月，胡广升任文渊阁大学士，仍兼原有春坊、翰林职务。", "start_year": 1416, "end_year": 1416, "time_original": "永樂14年（1416年）四月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "84af60de-5e1a-5b45-871b-94014df7912f"}, {"title": "蔡福等奉命在山东防御倭寇", "description": "永乐十四年六月丁卯，明廷命都督同知蔡福等人在山东防御倭寇。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年六月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "554b1168-46b4-5824-8827-eac7b2058679"}, {"title": "明廷派使赴北京、河南和山东捕蝗", "description": "永乐十四年七月丁酉，明廷派人到北京、河南、山东受灾州县捕灭蝗虫。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年七月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5c4eb0c0-1525-5120-890c-598523dbddc6"}, {"title": "黄河在开封决口", "description": "永乐十四年七月壬寅，黄河在开封决口。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年七月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e02f9145-685d-5775-a1ba-9f6b37955040"}, {"title": "纪纲获罪被处死", "description": "永乐十四年七月乙巳，主管锦衣卫事务的纪纲获罪被处死。本纪称他为锦衣卫指挥使，卷末校记引《太宗实录》作「掌锦衣卫事都指挥佥事」。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年七月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1333afd0-7a2e-54a1-9333-85e9eade5ded"}, {"title": "礼官因寿星出现请求上表庆贺，明成祖拒绝", "description": "永乐十四年八月癸酉清晨，本纪记载天上出现寿星。礼官请求上表庆贺，明成祖没有同意。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年八月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a446a4e5-3e35-555f-b738-e930d83f6b46"}, {"title": "明廷在北京修建西宫", "description": "永乐十四年八月丁亥，明廷开始修建北京西宫。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年八月丁亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "512eb11e-8e60-5005-a360-3eb4f3a2d91d"}, {"title": "京师发生地震", "description": "永乐十四年九月癸卯，本纪记载京师发生地震。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年九月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3aeabbff-1438-5664-8640-657326511e18"}, {"title": "明成祖启程离开北京", "description": "永乐十四年九月戊申，明成祖朱棣自北京启程南返。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年九月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b0ffd1d6-0ed8-57fd-874a-78dba472eec8"}, {"title": "明成祖到凤阳祭祀皇陵", "description": "永乐十四年十月丁丑，明成祖朱棣南行至凤阳，祭祀皇陵。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年十月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f7d19367-8576-5f04-9b78-9a272e1f74e1"}, {"title": "明成祖自北京归来后拜谒孝陵", "description": "永乐十四年十月癸未，明成祖朱棣自北京南返，拜谒明太祖的孝陵。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年十月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d001e626-c38c-5bdd-a3aa-608ba2eaa20b"}, {"title": "朝廷命文武大臣会商营建北京", "description": "永乐十四年十一月壬寅，明廷下诏召集文武大臣商议营建北京。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年十一月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b84d9f91-62d7-5cb3-9470-fa6d418cc2ef"}, {"title": "张辅奉召返回", "description": "永乐十四年十一月丙午，明廷召回张辅。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年十一月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8dcfb679-7c20-5cd4-904b-bc25f1fef6ea"}, {"title": "明廷削减汉王朱高煦的两支护卫", "description": "永乐十四年十一月戊申，汉王朱高煦获罪，朝廷削去他的两支护卫。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年十一月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "62d7f8eb-efdf-5b8f-806f-b82dbf960316"}, {"title": "朝廷迁山东等地流民至保安州并免役三年", "description": "永乐十四年十一月，朝廷将山东、山西、湖广的流民迁往保安州，并免除他们三年赋役。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "be1b14d9-6369-51af-bbba-23eb6e6be98e"}, {"title": "郑和又一次出使西洋", "description": "永乐十四年十二月丁卯，《明史》本纪记郑和再度出使西洋。换算原历日期，这一天已在公元1417年。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十四年十二月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f87afe9c-3d22-5dc3-9bdb-acc0ae1c439b"}, {"title": "本纪汇记永乐十四年多地入贡", "description": "永乐十四年，占城、古里、爪哇等地入贡，琉球中山两次入贡。本纪在年末合记各次来使。 按原历纪年，事情发生在公元1416至1417年之间。", "start_year": null, "end_year": null, "time_original": "永乐十四年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "39a0f9d6-33c3-581d-a236-bb8835c12771"}, {"title": "明成祖在南郊祭祀天地", "description": "永乐十五年正月丁酉，明成祖朱棣在南郊举行祭祀天地的大典。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年正月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c676714b-2fcc-55eb-9a7b-118b03ff0510"}, {"title": "平江伯陈瑄督办漕运，运输木材到北京", "description": "永乐十五年正月壬子，平江伯陈瑄督办漕运，将木料运往北京。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年正月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "36da2e47-9614-5649-b26a-f7926445df4e"}, {"title": "谷王朱橞获罪，被废为庶人", "description": "永乐十五年二月癸亥，谷王朱橞获罪，朝廷削去他的王爵，将他降为庶人。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年二月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "40926229-1225-5d72-994d-22dad716261b"}, {"title": "李彬奉命镇守交阯", "description": "永乐十五年二月丁卯，朝廷派丰城侯李彬镇守交阯。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年二月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f9ae13d1-ef42-5d6b-bd06-dbcf6b0a4689"}, {"title": "陈珪主持营建北京，柳升和王通协办", "description": "永乐十五年二月壬申，明廷命泰宁侯陈珪主持北京的营建工作，由柳升和王通协助。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年二月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6311f18c-b510-59d3-a09b-bc236f1dbf1c"}, {"title": "交阯首次送贡士到京师", "description": "永乐十五年三月丁亥，本纪记交阯首次向明廷选送贡士，贡士抵达京师。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年三月丁亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d77b2421-5a55-5f78-9cd1-261d732a4eb8"}, {"title": "朝廷发部分囚犯到北京服劳役赎罪", "description": "永乐十五年三月丙申，明廷将判为杂犯死罪及以下的囚犯发往北京服劳役，以劳役赎罪。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年三月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7fd7fc61-a5f9-5c8c-b2de-8bf30aa01968"}, {"title": "汉王朱高煦获罪改封乐安州", "description": "永乐十五年三月丙午，汉王朱高煦获罪，朝廷将他的封地改至乐安州。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年三月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a2c113c7-a68a-55a5-9525-447fef41f054"}, {"title": "明成祖离京北巡，朱高炽监国", "description": "永乐十五年三月壬子，明成祖朱棣离开京师前往北方巡行，皇太子朱高炽负责监理国政。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年三月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "82122a34-a661-51e0-919e-bb75468af221"}, {"title": "明成祖重申军士不得践踏庄稼，并令减免田租", "description": "永乐十五年四月己巳，明成祖行至邾城，重申军士不得践踏百姓田里的庄稼。庄稼受到损坏的，免收当年租税；有因水旱灾害积欠田租的，也予豁免。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年四月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "653046ac-d0a6-56c7-a9a8-19adc0d42b1f"}, {"title": "北京西宫建成", "description": "永乐十五年四月癸未，北京西宫建成。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年四月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f8461b15-9711-5a90-8a7c-aeda3f3b601c"}, {"title": "北巡的明成祖抵达北京", "description": "永乐十五年五月丙戌，明成祖朱棣抵达北京。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年五月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "84963fd6-9b1d-578e-9de4-91067aa15399"}, {"title": "李彬在交阯出兵并斩杀黎核", "description": "永乐十五年六月丁酉，李彬出兵攻打交阯与明军对抗的黎核，并将其斩杀。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年六月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "77d9151e-d5f2-575b-b0e1-9f0a44d26ca7"}, {"title": "中官张谦出使西洋后返回", "description": "永乐十五年六月己亥，中官张谦完成对西洋的出使后返回。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年六月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2ba4bf71-dbdc-5de8-89fd-a0506ef321d7"}, {"title": "倭寇在金乡卫被击败", "description": "永乐十五年六月，《明史》本纪记倭寇在金乡卫被击败。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "96c2bd35-f2c6-5f5c-bdc1-33d5a9c25b72"}, {"title": "明成祖命欧宁进丹人自行服丹，并销毁方书", "description": "永乐十五年八月甲午，瓯宁有人向朝廷进献金丹。明成祖朱棣认定他以方术惑众，命他自行服丹并销毁配方书。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年八月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7686c9bb-02f1-52ba-a080-c4d3c7953fc2"}, {"title": "曲阜孔子庙建成，明成祖撰文刻石", "description": "永乐十五年九月丁卯，曲阜孔子庙建成，明成祖朱棣亲自撰写文章并命人刻于石上。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年九月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d5da1978-b665-5196-accf-89305b991324"}, {"title": "李彬在交阯击败并斩杀杨进江", "description": "永乐十五年十月，李彬击败交阯一带与明军交战的杨进江所部，并斩杀杨进江。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a27f78c9-ef2a-520e-9f0b-c2e5e0ab4290"}, {"title": "赵羾出任兵部尚书，率军屯守边塞", "description": "永乐15年（年号对照1417年）十一月，赵羾出任兵部尚书，率军屯守边塞。原历日期只能确定在公元1417年至1418年之间，保留发生范围。", "start_year": null, "end_year": null, "time_original": "永乐15年（年号对照1417年）十一月；发生于公元1417至1418年之间，原文未标具体日。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "8a6e33fe-935b-5436-9788-c948e4d9c23c"}, {"title": "苏禄东西峒王来朝", "description": "永乐十五年，苏禄东峒王与西峒王来到明廷朝见。本纪将其列在年末汇记。 按原历纪年，事情发生在公元1417至1418年之间。", "start_year": null, "end_year": null, "time_original": "永乐十五年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "090da721-ea29-5a02-9eb8-a4ee922d6d58"}, {"title": "本纪汇记永乐十五年多地入贡", "description": "永乐十五年，琉球中山、别失八里、琉球山南、真腊、浡泥、占城、暹罗、哈烈和撒马儿罕先后来贡。 按原历纪年，事情发生在公元1417至1418年之间。", "start_year": null, "end_year": null, "time_original": "永乐十五年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "989c1ec9-8f2a-509b-a368-88c3d24ebff6"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

